/** One structure, rendered at its natural pixel size (w x h). */
export default function ZoneEntity({ id }: { id: ZoneId }) {
  const a = ZONE_ART[id]
  return (
    <svg
      viewBox={`${a.x} ${a.y} ${a.w} ${a.h}`}
      width={a.w}
      height={a.h}
      shapeRendering="crispEdges"
      style={{ display: 'block', overflow: 'visible' }}
      dangerouslySetInnerHTML={{ __html: a.inner }}
    />
  )
}
